    assert exit_code == FailingRequest.exit_code([bad_address])
    assert stderr == dedent(
        """\

        𐄂 ConditionallySucceedsChecker failed.
        𐄂 FailingChecker failed.
        - SkippedChecker skipped.
        ✓ SuccessfulChecker succeeded.
        """
    )


