class Solution(object):
    def firstBadVersion(self, n):
        start = 1
        end = n

        while start + 1 < end:
            mid = start + (end - start) / 2
            if isBadVersion(mid):
                end = mid
            else:
                start = mid

        if isBadVersion(start):
            return start
        elif isBadVersion(end):
            return end

