    #moved to INTPoint.py
    return INTPoint.getMidPoint(line)

def getArch(line,point):
    #moved to INTPoint.py
    return INTPoint.getArch(line,point)

def voteForPoint(lines):
    #moved to INTPoint.py
    global votes
    global voters
    votes,voters = INTPoint.voteForPoint(lines,VPoints)
    return

def getGraPoint(points):
    count = 1.0
    sumx = 0.0
    sumy = 0.0
    for point in points:
        w = votes[point]
        count += w
        sumx += w * point[0]
        sumy += w * point[1]
    return (sumx/count,sumy/count)

def devideIntoPoints(Points):
    global Cluster
    lens = len(Cluster)
    for i in range(0,lens,1):
        Cluster[i] = []

    for point in Points:
        if point[0] == 'p' or point[0] == 'h' or point[0] == 'v':
            continue
        if votes[point] == 0:
            continue
        minlens = 1e15
        minpos = 0
        now = -1
        for cen in Centers:
            now += 1
            lens = getLinesLength((point[0],point[1],cen[0],cen[1]))
            if lens < minlens:
                minlens = lens
                minpos = now
        Cluster[minpos].append(point)

def KMean(points,K = 3,step = 50):
    global Cluster
    global Centers
    Cluster = []
    Centers = []
    if K == 1:
        step = 1
    for i in range(0,K,1):
        Cluster.append([])
        Centers.append([0,0])

    count = 0
    for point in points:
        if point[0] != 'p' and point[0] != 'v' and point[0] != 'h' and votes[point] != 0:
            Centers[count][0] = point[0]
            Centers[count][1] = point[1]
            count += 1
        if count == K:
            break

    for i in range(0,step,1):
        devideIntoPoints(points)
        for i in range(0,K,1):
            Centers[i] = getGraPoint(Cluster[i])

def getFinal(points):
    count = 0.0
    num = 0
    p1 = 0.0
    ret1 = []
    p2 = 0.0
    ret2 = []
    for item in votes:
        if item[0] == 'p' or item[0] == 'h' or item[0] == 'v':
            if votes[item] > p1:
                p2 = p1
                ret2 = ret1
                p1 = votes[item]
                ret1 = item
            else:
                if votes[item] > p2:
                    p2 = votes[item]
                    ret2 = item
        else:
            count += votes[item]
            num += 1
    K = 3
    ret = []
    count = count / num * 0.1
    if p1 > count:
        K -= 1
        ret.append(ret1)
    if p2 > count:
        K -= 1
        ret.append(ret2)
    KMean(points,K)
    for i in range(0,K,1):
        ret.append(Centers[i])
    return ret

def deal(inputname,outputname):
    global votes
    global Groups
    global VPoints
    global Centers
    global Cluster
    global voters
    votes = {}
    Groups = []
    VPoints = []
    Centers = []
    Cluster = []
    voters = {}
    image = cv.imread(inputname)
    edges = getEdges(image)
    cv.imwrite(outputname + 'edges.jpg',edges)
    lines = getLines(edges)
    lines2 = copy.deepcopy(lines)
    lines2 = extenLines(lines2,edges)
    lines2 = mergeLines(lines2)

    #devideIntoGroups(lines2,3)
    lines2 = sortLines(lines2)
    getVPoints2(lines2)

