    if (key=='s' or key=='S'):
        saveFrame(datetime.now().strftime("%Y%m%d%H%M%S")+".png")
    if (key=='p' or key=='P'):
        savePDF = True

    if key == "1":
        actStrokeCap = ROUND
    elif key == "2":
        actStrokeCap = SQUARE
    elif key == "3":
        actStrokeCap = PROJECT
    elif (key == '4'):
        if (colorLeft == color(0)):
            colorLeft = color(323, 100, 77)
