def user_role_to_cfg(username, urole, cfg):
    tmp = ['roles', 'subroles'] \
      + urole['path'].replace('/', '/subroles/').split('/')

    tmp = get_subdict(cfg, tmp, default_empty=True)
    setdefault_none(setdefault_none(tmp, 'members', {}), 
       urole['level'], []
    ).append(username)


