class Setup1:
    """
    Constant bathymetry and u velocty, zero diffusivity, non-trivial tracer
    """
    def bath(self, x, y, lx, ly):
        return Constant(40.0)

    def elev(self, x, y, lx, ly):
        return Constant(0.0)

    def uv(self, x, y, z, lx, ly):
        return as_vector(
            [
                Constant(1.0),
                Constant(0.0),
                Constant(0),
            ])

    def w(self, x, y, z, lx, ly):
        return as_vector(
            [
                Constant(0),
                Constant(0),
                Constant(0),
            ])

