    def to_alipay_dict(self):
        params = dict()
        if self.dest_geo:
            if hasattr(self.dest_geo, 'to_alipay_dict'):
                params['dest_geo'] = self.dest_geo.to_alipay_dict()
            else:
                params['dest_geo'] = self.dest_geo
        if self.od:
            if hasattr(self.od, 'to_alipay_dict'):
