                params['work_od'] = self.work_od.to_alipay_dict()
            else:
                params['work_od'] = self.work_od
        return params

    @staticmethod
    def from_alipay_dict(d):
        if not d:
            return None
        o = MetroOdItem()
        if 'dest_geo' in d:
            o.dest_geo = d['dest_geo']
        if 'od' in d:
            o.od = d['od']
        if 'time' in d:
