class Transaction(object):
    def __init__(self, **kwargs):
        self._completed_at = kwargs.get('completed_at')
        self._type = kwargs.get('type')
        self._symbol = kwargs.get('symbol')
        self._price = kwargs.get('price')
        self._amount = kwargs.get('amount')

    def __eq__(self, other):
        if self.completed_at != other.completed_at:
            return False
        if self.type != other.type:
            return False
        if self.symbol != other.symbol:
            return False
        if self.price != other.price:
            return False
        if self.amount != other.amount:
            return False
        return True

    def get_cn_type(self):
        return u'买入' if self.type == 'BUY' else u'卖出'

    @property
    def completed_at(self):
        return self._completed_at

    @completed_at.setter
    def completed_at(self, value):
        self._completed_at = value

    @property
    def type(self):
        return self._type

    @type.setter
    def type(self, value):
        self._type = value

    @property
    def symbol(self):
        return self._symbol

    @symbol.setter
    def symbol(self, value):
        self._symbol = value

    @property
    def price(self):
        return self._price

    @price.setter
    def price(self, value):
        self._price = value

    @property
    def amount(self):
        return self._amount

    @amount.setter
    def amount(self, value):
        self._amount = value

class Event:
    def __init__(self):
        self.handlers = set()

    def subscribe(self, func):
        self.handlers.add(func)

    def unsubscribe(self, func):
        self.handlers.remove(func)

    def emit(self, *args):
        for func in self.handlers:
            func(*args)

import os


def check_env(env_var_name):
    """
    Check and return the type of an environment variable.

    supported types:
        None
        Integer
        String

    @param env_var_name: environment variable name
    @return: string of the type name.
    """
    try:
        val = os.getenv(env_var_name)
        if val is None:
            return 'None'
    except Exception as ex:
        return "None"

    try:
        int_val = int(val)
        return 'Integer'
    except ValueError:
        return 'String'

